const slots = $slots;
probe(Number.isInteger(slots.throughput) && slots.throughput > 0, "the nominal throughput must be a positive whole number of cases per hour");
probe(Number.isInteger(slots.overheadPercent) && slots.overheadPercent > 0 && slots.overheadPercent < 100, "the overhead must be a whole number between 0 and 100 percent");
probe(Number.isInteger(slots.minutes) && slots.minutes > 0, "the process must run a positive whole number of minutes");
const usefulPercent = slots.overheadPercent / 100;
probe(usefulPercent > 0 && usefulPercent < 100, "the overhead must leave some useful output");
const timeHours = slots.minutes / slots.throughput;
probe(timeHours > 0, "the process time must be positive");
const rateHundredthsOf = (usefulPercent * 100) / timeHours;
probe(rateHundredthsOf > 0, "the rate must be positive because the process time divides into whole hours");
const formatTime = (hours) => {
  const wrapped = ((hours % 1440) + 1440) % 1440;
  return String(Math.floor(wrapped / 60)).padStart(2, "0") + ":" + String(wrapped % 60).padStart(2, "0");
};
const time = formatTime(timeHours);
const rate = Math.trunc(rateHundredthsOf / 100) + "." + String(rateHundredthsOf % 100).padStart(2, "0");
return "Useful output: " + formatNumber(usefulPercent) + "%. Time " + time + " hours. Rate " + rate + " g/hour.";

